// TestHiddenConcurrent (FAIL_TO_PASS: the new answers): Fold and Rank from 4 goroutines at once (run with -race).
func TestHiddenConcurrent(t *testing.T) {
	var wg sync.WaitGroup
	for g := 0; g < 4; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for _, c := range hiddenFoldChanged {
				if hot.Fold(c.in) != c.out {
					t.Error("Fold differs under concurrency")
					return
				}
			}
		}()
	}
	wg.Wait()
	hiddenRankConcurrently(t, hiddenRankFolded[:min(8, len(hiddenRankFolded))])
}
